def reconciler_summary() -> dict:
    path = RUNTIME / "reconciler.json"
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {"available": False, "generated_at_utc": None, "claims": [], "orphan_processing": []}
    claims = []
    for row in data.get("claims") or []:
        if not isinstance(row, dict):
            continue
        claims.append({
            "agent_id": row.get("agent_id"),
            "task_id": row.get("task_id"),
            "worktree": row.get("worktree"),
            "decision": row.get("decision"),
            "released": bool(row.get("released")),
            "release_reason": row.get("release_reason"),
        })
    orphan_processing = []
    for row in data.get("orphan_processing") or []:
        if not isinstance(row, dict):
            continue
        orphan_processing.append({"job_id": row.get("job_id"), "action": row.get("action")})
    return {
        "available": True,
        "generated_at_utc": data.get("generated_at_utc"),
        "claims": claims,
        "orphan_processing": orphan_processing,
        "production_touched": bool(data.get("production_touched", False)),
    }
